  "bestCut.consent": "최적의 테이크를 찾기 위해 선택한 동영상 파일 전체를 Veyrnox.ai에 업로드하고 오디오를 읽는 음성 전사 서비스로 보냅니다. 대본과 메모는 이 휴대전화에 남습니다. 임시 전사용 업로드는 24시간 후 삭제 예정이며 정리는 더 오래 걸릴 수 있습니다. 중복 청구를 피하기 위해 전사 텍스트는 최대 30일 보관됩니다. 계정을 삭제하면 전사 텍스트도 삭제됩니다. 라이브러리 원본과 프로젝트 백업에는 별도의 보관 정책이 적용됩니다. 아무도 말하지 않으면 요금이 청구되지 않습니다.",
  "bestCut.metadata": "선택한 파일, 길이와 콘텐츠 유형, 계정 ID, 요청 키만 휴대전화 밖으로 전송됩니다. 위치 정보나 EXIF 메타데이터를 제거하지 않습니다. iOS 음성 인식 권한은 필요하지 않습니다.",
